Death By Captcha http Client */
Client client = (Client) new HttpClient(username, password);
/* To use token authentication the first parameter must
be "authtoken".
Client client = (Client) new HttpClient("authtoken",
token_from_panel); */
// Put your Proxy credentials and type here
string proxy = "http://user:[email protected]:1234";
string proxyType = "HTTP";
string pageurl = "https://datadome.co/book-live-product-demo";
string captcha_url = "https://datadome.co/book-live-product-demo";
string datadomeParams = "{\"proxy\": \"" + proxy + "\"," +
"\"proxytype\": \"" + proxyType + "\"," +
"\"pageurl\": \"" + pageurl + "\"," +
"\"captcha_url\": \"" + captcha_url + "}"
try
{
double balance = client.GetBalance();
/* Upload a CAPTCHA and poll for its status. Put the Datadome
Json payload, CAPTCHA type and desired solving timeout (in seconds)
here. If solved, you'll receive a DeathByCaptcha.Captcha object. */
Captcha captcha = client.Decode(Client.DefaultTimeout,
new Hashtable()
{
{"type", 21},
{"datadome_params", datadomeParams}
});
if (null != captcha)
{
/* The CAPTCHA was solved; captcha.Id property holds
its numeric ID, and captcha.Text holds its text. */
Console.WriteLine("CAPTCHA {0} solved: {1}",
captcha.Id, captcha.Text);
// if ( /* check if the CAPTCHA was incorrectly solved */)
